use chrono::{DateTime, Utc};
use std::{collections::{BTreeMap, BTreeSet}, num::NonZeroUsize};
use crate::domain::{models::updates::{EntityUpdate, MonthlyUpdates, RegistrationMonth, UpdatedCompany}, repositories::updates::{UpdatesError, UpdatesRepo}};
/// Complete current-month operation with a request-owned clock instant.
pub trait UpdatesService: Clone + Send + Sync + 'static {
    /// Returns every identity updated in the instant's UTC calendar month.
    fn updates(&self, now: DateTime<Utc>) -> impl Future<Output = Result<MonthlyUpdates, UpdatesError>> + Send;
