/// Monthly activity application service.
#[derive(Clone)]
pub struct Service<R> { repo: R }
impl<R> Service<R> {
    /// Creates the service.
    pub const fn new(repo: R) -> Self { Self { repo } }
}
struct Activity<I> { identity: I, sources: BTreeSet<i32>, latest: DateTime<Utc> }
fn observe<K: Ord, I>(groups: &mut BTreeMap<K, Activity<I>>, key: K, identity: I, source: i32, date: DateTime<Utc>) {
    let activity = groups.entry(key).or_insert_with(|| Activity { identity, sources: BTreeSet::new(), latest: date });
    activity.sources.insert(source);
    activity.latest = activity.latest.max(date);
}
fn rows<K: Ord, I>(groups: BTreeMap<K, Activity<I>>, name: impl Fn(&I) -> &str) -> Vec<EntityUpdate<I>> {
    let mut rows: Vec<_> = groups.into_iter().collect();
    rows.sort_by(|a, b| b.1.latest.cmp(&a.1.latest).then_with(|| name(&a.1.identity).cmp(name(&b.1.identity))).then_with(|| a.0.cmp(&b.0)));
    rows.into_iter().map(|(_, activity)| EntityUpdate { identity: activity.identity, declaration_count: NonZeroUsize::new(activity.sources.len()).expect("observed activity has a source"), latest_registration: activity.latest }).collect()
}
impl<R: UpdatesRepo> UpdatesService for Service<R> {
    async fn updates(&self, now: DateTime<Utc>) -> Result<MonthlyUpdates, UpdatesError> {
